file_editor: {"command": "create", "path": "/app/workspace/extract.py", "file_text": "import os
import re
import sys
from pathlib import Path
import pytesseract
from PIL import Image, ImageOps, ImageFilter
from openpyxl import Workbook

IMG_DIR = Path("/app/workspace/dataset/img")
OUT_XLSX = Path("/app/workspace/stat_ocr.xlsx")

MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

MONEY_STRICT = re.compile(r'(?<![\d.])(\d{1,3}(?:,\d{3})+|\d+)\.(\d{2})(?![\d.])')

PRIMARY_KEYWORDS = [
    ("GRAND TOTAL", 100),
    ("TOTAL RM", 90),
    ("TOTAL: RM", 90),
    ("TOTAL AMOUNT", 80),
    ("TOTAL DUE", 70),
    ("AMOUNT DUE", 70),
    ("BALANCE DUE", 70),
    ("NETT TOTAL", 70),
    ("NET TOTAL", 70),
    ("TOTAL", 60),
    ("AMOUNT", 60),
]

EXCLUSION = ["SUBTOTAL", "SUB TOTAL", "TAX", "GST", "SST", "DISCOUNT", "CHANGE", "CASH TENDERED"]


def parse_money(token):
    if token is None:
        return None
    s = str(token).strip().replace('"', '').replace('~', '').replace('—', '')
    m = MONEY_STRICT.search(s)
    if m:
        return m.group(1).replace(',', '') + '.' + m.group(2)
    s2 = re.sub(r'(\d)[:;](\d{2})\b', r'\1.\2', s)
    m = MONEY_STRICT.search(s2)
    if m:
        return m.group(1).replace(',', '') + '.' + m.group(2)
    s3 = re.sub(r'(\d)\s+(\d{2})\b', r'\1.\2', s)
    m = MONEY_STRICT.search(s3)
    if m:
        return m.group(1).replace(',', '') + '.' + m.group(2)
    return None


def extract_last_money(line):
    """Extract last monetary value from a line."""
    matches = list(MONEY_STRICT.finditer(line))
    if matches:
        m = matches[-1]
        return m.group(1).replace(',', '') + '.' + m.group(2)
    return None


def line_has_exclusion(line_upper, primary_keyword):
    """Check if the line should be excluded, except GRAND TOTAL overrides."""
    if primary_keyword == "GRAND TOTAL":
        return False
    for ex in EXCLUSION:
        if ex in line_upper:
            return True
    return False


def find_total(text):
    """Find the total amount using tiered keyword priority."""
    lines = text.split('\n')
    candidates = []  # (priority, keyword, value)

    for i, line in enumerate(lines):
        upper = line.upper()
        for kw, prio in PRIMARY_KEYWORDS:
            if kw in upper:
                if line_has_exclusion(upper, kw):
                    continue
                # Try to find money on same line
                val = extract_last_money(line)
                if val is None:
                    # Fallback: look at next non-blank line
                    for j in range(i + 1, min(i + 4, len(lines))):
                        nxt = lines[j].strip()
                        if not nxt:
                            continue
                        val = extract_last_money(nxt)
                        if val is None:
                            # Try repair
                            val = parse_money(nxt.split()[-1] if nxt.split() else "")
                        if val:
                            break
                if val is None:
                    # Try repairing same line
                    tokens = re.findall(r'[\d:.,]+', line)
                    if tokens:
                        val = parse_money(tokens[-1])
                if val:
                    candidates.append((prio, kw, val))
                break  # only match first keyword per line

    if not candidates:
        return None
    candidates.sort(key=lambda x: -x[0])
    return candidates[0][2]


DATE_PATTERNS = [
    # dd/mm/yyyy or dd-mm-yyyy
    (re.compile(r'\b(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2,4})\b'), 'dmy'),
    # yyyy/mm/dd
    (re.compile(r'\b(\d{4})[/\-\.](\d{1,2})[/\-\.](\d{1,2})\b'), 'ymd'),
    # dd MMM yyyy
    (re.compile(r'\b(\d{1,2})[\s\-]+([A-Za-z]{3,9})[\s\-,]+(\d{2,4})\b'), 'dMy'),
    # MMM dd, yyyy
    (re.compile(r'\b([A-Za-z]{3,9})[\s\-]+(\d{1,2})[\s\-,]+(\d{2,4})\b'), 'Mdy'),
]


def normalize_year(y):
    y = int(y)
    if y < 100:
        y = 2000 + y if y < 70 else 1900 + y
    return y


def valid_date(y, m, d):
    if not (1 <= m <= 12):
        return False
    if not (1 <= d <= 31):
        return False
    if not (2000 <= y <= 2099):
        return False
    return True


def find_date(text):
    for line in text.split('\n'):
        for pat, kind in DATE_PATTERNS:
            for m in pat.finditer(line):
                try:
                    if kind == 'dmy':
                        d, mo, y = int(m.group(1)), int(m.group(2)), normalize_year(m.group(3))
                    elif kind == 'ymd':
                        y, mo, d = normalize_year(m.group(1)), int(m.group(2)), int(m.group(3))
                    elif kind == 'dMy':
                        mon_str = m.group(2).lower()
                        if mon_str not in MONTHS:
                            continue
                        d, mo, y = int(m.group(1)), MONTHS[mon_str], normalize_year(m.group(3))
                    elif kind == 'Mdy':
                        mon_str = m.group(1).lower()
                        if mon_str not in MONTHS:
                            continue
                        mo, d, y = MONTHS[mon_str], int(m.group(2)), normalize_year(m.group(3))
                    if valid_date(y, mo, d):
                        return f"{y:04d}-{mo:02d}-{d:02d}"
                except Exception:
                    continue
    return None


def ocr_variants(img_path):
    img = Image.open(img_path)
    gray = ImageOps.grayscale(img)
    w, h = img.size
    variants = [
        ("gray_auto", ImageOps.autocontrast(gray)),
        ("sharp", gray.filter(ImageFilter.SHARPEN)),
        ("up3x", ImageOps.autocontrast(img.resize((w * 3, h * 3), Image.LANCZOS).convert('L'))),
    ]
    psm_modes = ['--psm 6', '--psm 4', '--psm 11']
    texts = []
    for name, v in variants:
        for psm in psm_modes:
            try:
                t = pytesseract.image_to_string(v, config=psm)
                if t.strip():
                    texts.append(t)
            except Exception:
                pass
    return texts


def vote(values):
    """Return majority value, or first if tie."""
    counts = {}
    order = []
    for v in values:
        if v is None:
            continue
        if v not in counts:
            counts[v] = 0
            order.append(v)
        counts[v] += 1
    if not counts:
        return None
    best = max(order, key=lambda x: (counts[x], -order.index(x)))
    return best


def process_image(img_path):
    texts = ocr_variants(img_path)
    dates = []
    totals = []
    for t in texts:
        d = find_date(t)
        tot = find_total(t)
        dates.append(d)
        totals.append(tot)
    date = vote(dates)
    total = vote(totals)
    return date, total


def main():
    files = sorted([f for f in os.listdir(IMG_DIR) if f.lower().endswith(('.jpg', '.jpeg', '.png'))])
    rows = []
    for fname in files:
        print(f"Processing {fname}...", flush=True)
        try:
            date, total = process_image(IMG_DIR / fname)
        except Exception as e:
            print(f"  ERROR: {e}")
            date, total = None, None
        print(f"  date={date} total={total}")
        rows.append((fname, date, total))

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for fname, date, total in rows:
        ws.append([fname, date, total])
    wb.save(OUT_XLSX)
    print(f"Wrote {OUT_XLSX}")


if __name__ == "__main__":
    main()
